exec('\nfrom __future__ import annotations\n\nimport time\nimport warnings\nimport xml.etree.ElementTree as ET\nfrom pathlib import Path\nfrom urllib.parse import quote_plus\nimport datetime as dt\n\nimport numpy as np\nimport pandas as pd\nimport streamlit as st\nimport yfinance as yf\nimport requests\nimport plotly.graph_objects as go\nimport plotly.express as px\n\nfrom sklearn.linear_model import Ridge, ElasticNet, HuberRegressor\nfrom sklearn.ensemble import RandomForestRegressor, ExtraTreesRegressor, GradientBoostingRegressor, VotingRegressor\nfrom sklearn.metrics import mean_squared_error\n\nwarnings.filterwarnings("ignore")\nROOT = Path(__file__).resolve().parents[1]\n\n# -----------------------------------------------------------------------------\n# Built-in knowledge layer\n# -----------------------------------------------------------------------------\nDEFAULT_MATERIALS = {\n    "Copper": {"long_name": "Copper — electrical conductivity and industrial demand", "tickers": ["HG=F", "CPER", "COPX"], "family": "industrial_metals", "role": "grids, motors, electronics, construction, EVs, industrial cycle", "weight": 0.11},\n    "Aluminum": {"long_name": "Aluminum — lightweight structures and energy-intensive smelting", "tickers": ["ALI=F", "AA"], "family": "industrial_metals", "role": "aerospace, automotive, packaging, transport, power-intensive smelting", "weight": 0.09},\n    "IronOre": {"long_name": "Iron ore — steelmaking and China construction cycle", "tickers": ["TIO=F", "RIO", "BHP", "VALE"], "family": "steel_chain", "role": "blast furnace feedstock, steel demand, infrastructure, China construction", "weight": 0.075},\n    "Steel": {"long_name": "Steel — manufacturing, construction and capital-goods cycle", "tickers": ["SLX", "MT", "NUE", "X"], "family": "steel_chain", "role": "construction, heavy equipment, automotive, industrial capex", "weight": 0.065},\n    "CokingCoal": {"long_name": "Coking coal — metallurgical coal for steelmaking", "tickers": ["HCC", "BTU", "ARCH"], "family": "steel_chain", "role": "blast furnace steelmaking input; different from thermal coal", "weight": 0.045},\n    "ThermalCoal": {"long_name": "Thermal coal — power generation and energy-security stress", "tickers": ["BTU", "CEIX", "WHC.AX"], "family": "energy_inputs", "role": "electricity generation, industrial power cost, Asian energy demand", "weight": 0.04},\n    "Lithium": {"long_name": "Lithium — battery and energy-storage supply chain", "tickers": ["LIT", "ALB", "SQM", "PLL"], "family": "battery_materials", "role": "EV batteries, energy storage, cathode materials", "weight": 0.075},\n    "Cobalt": {"long_name": "Cobalt — cathode material and geopolitical supply risk", "tickers": ["COB.AX", "GLEN.L", "VALE"], "family": "battery_materials", "role": "battery cathodes, strategic supply, refining concentration", "weight": 0.045},\n    "Graphite": {"long_name": "Graphite — battery anode and China processing risk", "tickers": ["NMG", "SYAAF", "TGR.AX"], "family": "battery_materials", "role": "battery anodes, China-dependent processing, export-control sensitivity", "weight": 0.045},\n    "RareEarths": {"long_name": "Rare earths — permanent magnets, EVs, wind and defense electronics", "tickers": ["REMX", "MP", "LYC.AX"], "family": "rare_earths", "role": "NdFeB magnets, defense electronics, EV motors, wind turbines", "weight": 0.09},\n    "Neodymium": {"long_name": "Neodymium — high-strength magnet material", "tickers": ["REMX", "MP", "LYC.AX"], "family": "rare_earths", "role": "NdFeB magnets for EV motors, wind turbines and precision systems", "weight": 0.045},\n    "Dysprosium": {"long_name": "Dysprosium — high-temperature magnet additive", "tickers": ["REMX", "MP", "LYC.AX"], "family": "rare_earths", "role": "high-temperature magnets for EV, aerospace and defense electronics", "weight": 0.04},\n    "Titanium": {"long_name": "Titanium — aerospace, medical and AM powder alloy base", "tickers": ["ATI", "TROX", "CRS", "TITN"], "family": "aerospace_defense_materials", "role": "Ti-6Al-4V, aerospace structures, medical implants, LPBF/EBM powder feedstock", "weight": 0.07},\n    "Nickel": {"long_name": "Nickel — stainless steel, superalloys and battery cathodes", "tickers": ["JJN", "VALE", "NILSY"], "family": "superalloys_battery_metals", "role": "stainless steel, Ni superalloys, turbine components, batteries", "weight": 0.08},\n    "Tungsten": {"long_name": "Tungsten — hard metals, tooling and defense materials", "tickers": ["TUNG.L", "ALMTF"], "family": "aerospace_defense_materials", "role": "cemented carbides, machining, penetrators, defense and tooling", "weight": 0.04},\n    "Uranium": {"long_name": "Uranium — nuclear fuel and energy-security supply chain", "tickers": ["URA", "URNM", "CCJ"], "family": "energy_security", "role": "nuclear fuel, grid reliability, energy independence", "weight": 0.07},\n    "Oil": {"long_name": "WTI crude oil — fuel, logistics and inflation pressure", "tickers": ["CL=F", "USO", "XLE"], "family": "energy_inputs", "role": "transport, fuel, energy cost, petrochemicals, geopolitical risk", "weight": 0.10},\n    "BrentOil": {"long_name": "Brent oil — global oil and Middle East/Europe risk", "tickers": ["BZ=F", "BNO"], "family": "energy_inputs", "role": "global oil benchmark, fuel cost, Middle East and Europe energy risk", "weight": 0.08},\n    "NaturalGas": {"long_name": "Natural gas — power, heat treatment and process-energy cost", "tickers": ["NG=F", "UNG", "BOIL"], "family": "energy_inputs", "role": "power, heat treatment, HIP/process gas cost, chemicals, smelting", "weight": 0.08},\n    "Gold": {"long_name": "Gold — safe-haven, real-rate and geopolitical stress gauge", "tickers": ["GC=F", "GLD"], "family": "precious_stress", "role": "safe haven, real rates, central-bank demand, crisis hedging", "weight": 0.07},\n    "Silver": {"long_name": "Silver — precious/industrial hybrid metal", "tickers": ["SI=F", "SLV"], "family": "precious_industrial", "role": "solar, electronics, brazing, precious-metal demand", "weight": 0.045},\n    "Platinum": {"long_name": "Platinum — catalysts, hydrogen and industrial demand", "tickers": ["PL=F", "PPLT"], "family": "precious_industrial", "role": "auto catalysts, hydrogen electrolysis/fuel cells, chemical industry", "weight": 0.04},\n    "Palladium": {"long_name": "Palladium — auto catalyst and supply-risk metal", "tickers": ["PA=F", "PALL"], "family": "precious_industrial", "role": "gasoline auto catalysts, industrial demand, Russia supply risk", "weight": 0.04},\n}\n\nDEFAULT_MACRO = {\n    "USDIndex": "DX-Y.NYB",\n    "VIX": "^VIX",\n    "US10Y": "^TNX",\n    "US13Week": "^IRX",\n    "HighYieldCredit": "HYG",\n    "InvestmentGradeCredit": "LQD",\n    "EURUSD": "EURUSD=X",\n    "USDCNY": "CNY=X",\n    "USDJPY": "JPY=X",\n    "FreightProxy": "BDRY",\n    "EnergyEquity": "XLE",\n    "Semiconductors": "SOXX",\n}\n\nDEFAULT_INDICES = {\n    "USA": {"S&P 500": "^GSPC", "Nasdaq 100": "^NDX", "Russell 2000": "^RUT", "Dow Jones": "^DJI", "Industrials": "XLI", "Materials": "XLB", "Energy": "XLE", "Aerospace/Defense": "ITA"},\n    "Europe": {"DAX": "^GDAXI", "CAC 40": "^FCHI", "FTSE 100": "^FTSE", "FTSE MIB": "FTSEMIB.MI", "Europe ETF": "VGK"},\n    "China / Hong Kong": {"CSI 300": "000300.SS", "SSE Composite": "000001.SS", "Hang Seng": "^HSI", "China Large Cap": "FXI"},\n    "Japan": {"Nikkei 225": "^N225", "Japan ETF": "EWJ"},\n    "Global": {"World proxy": "URTH", "Emerging markets": "EEM", "Global industrials": "EXI", "Global materials": "MXI"},\n}\n\nFUTURES_UNIVERSE = {\n    "WTI crude oil future": "CL=F",\n    "Brent oil future": "BZ=F",\n    "Natural gas future": "NG=F",\n    "Copper future": "HG=F",\n    "Gold future": "GC=F",\n    "Silver future": "SI=F",\n    "Platinum future": "PL=F",\n    "Palladium future": "PA=F",\n    "Iron ore future/proxy": "TIO=F",\n    "US Dollar Index": "DX-Y.NYB",\n    "VIX Index": "^VIX",\n    "US 10Y yield": "^TNX",\n    "Gold ETF": "GLD",\n    "Silver ETF": "SLV",\n    "Oil ETF": "USO",\n    "Natural gas ETF": "UNG",\n    "Uranium ETF": "URA",\n    "Rare earth ETF": "REMX",\n    "Lithium/Battery ETF": "LIT",\n    "Steel ETF": "SLX",\n}\n\nDEFAULT_GEO_TERMS = [\n    "critical minerals", "rare earth", "war", "Iran", "Middle East", "oil", "gas",\n    "LNG", "gold", "silver", "China", "Taiwan", "sanctions", "export controls",\n    "Strait of Hormuz", "defense spending", "aerospace", "titanium", "powder metallurgy"\n]\n\nEXPOSURE_DEFS = {\n    "copper": "Copper exposure through electrification, motors, grids, electronics or mining.",\n    "aluminum": "Aluminum exposure through aerospace, transport, packaging, smelting and energy costs.",\n    "nickel": "Nickel exposure through stainless steel, Ni superalloys, batteries and turbine materials.",\n    "steel_chain": "Iron ore, steel, coking coal and industrial construction sensitivity.",\n    "battery": "Lithium, cobalt, graphite, nickel and battery supply-chain sensitivity.",\n    "rare_earths": "NdPr/Dy/Tb magnet materials, defense electronics, EV motors and export-control sensitivity.",\n    "energy": "Oil, gas, power and fuel-cost sensitivity.",\n    "coal": "Thermal/coking coal exposure through power or steelmaking.",\n    "uranium": "Nuclear fuel and energy-security sensitivity.",\n    "aerospace": "Aerospace build-rate and materials demand sensitivity.",\n    "defense": "Defense procurement, munitions and strategic-material sensitivity.",\n    "semiconductor": "Semiconductor cycle, electronics materials and Taiwan/China risk sensitivity.",\n    "additive_manufacturing": "Industrial AM exposure through powder feedstock, aerospace/medical/defense demand and risk appetite.",\n    "china_sensitivity": "China demand, China policy and China-linked supply-chain sensitivity.",\n    "geopolitical_sensitivity": "Sanctions, war, shipping disruption and policy-event sensitivity.",\n    "macro_beta": "General rate, credit, USD and risk-appetite sensitivity.",\n}\n\nUI_TEXT = {\n    "product_title": "MatQuantLab",\n    "subtitle": "Material-driven industrial risk research",\n    "description": "A workbench for studying how material, energy, macro and geopolitical shocks transmit into manufacturing-linked assets.",\n}\n\n# -----------------------------------------------------------------------------\n# Loaders and data access\n# -----------------------------------------------------------------------------\ndef load_yaml(path, fallback):\n    try:\n        import yaml\n        p = ROOT / path\n        if p.exists():\n            return yaml.safe_load(p.read_text(encoding="utf-8")) or fallback\n    except Exception:\n        pass\n    return fallback\n\ndef load_csv(path, fallback):\n    p = ROOT / path\n    try:\n        if p.exists():\n            return pd.read_csv(p).drop_duplicates()\n    except Exception:\n        pass\n    return fallback\n\ndef normalize_materials(data):\n    mats = data.get("materials", data) if isinstance(data, dict) else {}\n    merged = DEFAULT_MATERIALS.copy()\n    if isinstance(mats, dict):\n        merged.update(mats)\n    return merged\n\ndef normalize_macro(data):\n    raw = data.get("macro_proxies", data) if isinstance(data, dict) else {}\n    out = DEFAULT_MACRO.copy()\n    if isinstance(raw, dict):\n        for k, v in raw.items():\n            out[k] = v.get("ticker", v) if isinstance(v, dict) else v\n    return out\n\ndef normalize_indices(data):\n    return data.get("indices", data) if isinstance(data, dict) and data else DEFAULT_INDICES\n\ndef fallback_exposure():\n    base = [\n        {"asset": "SPY", "full_name": "SPDR S&P 500 ETF Trust", "theme": "US market benchmark", "region": "USA", "macro_beta": 1.0},\n        {"asset": "XME", "full_name": "SPDR S&P Metals & Mining ETF", "theme": "Mining/metals", "region": "USA", "copper": .7, "steel_chain": .8, "energy": .5, "macro_beta": .7},\n        {"asset": "COPX", "full_name": "Global X Copper Miners ETF", "theme": "Copper miners", "region": "Global", "copper": 1.0, "energy": .3, "china_sensitivity": .6, "macro_beta": .7},\n        {"asset": "ITA", "full_name": "iShares U.S. Aerospace & Defense ETF", "theme": "Aerospace/defense", "region": "USA", "aluminum": .6, "nickel": .5, "aerospace": 1, "defense": 1, "rare_earths": .4, "energy": .6},\n        {"asset": "XAR", "full_name": "SPDR S&P Aerospace & Defense ETF", "theme": "Aerospace supply chain", "region": "USA", "aluminum": .7, "nickel": .5, "aerospace": 1, "defense": .8, "energy": .6},\n        {"asset": "PRNT", "full_name": "The 3D Printing ETF", "theme": "Additive manufacturing ETF", "region": "Global", "titanium": .6, "aluminum": .4, "nickel": .3, "aerospace": .3, "additive_manufacturing": 1.0, "energy": .4},\n        {"asset": "GLD", "full_name": "SPDR Gold Shares", "theme": "Gold / safe haven", "region": "Global", "gold": 1.0, "geopolitical_sensitivity": .8, "macro_beta": .4},\n        {"asset": "SLV", "full_name": "iShares Silver Trust", "theme": "Silver / industrial precious", "region": "Global", "silver": 1.0, "semiconductor": .4, "macro_beta": .5},\n        {"asset": "URA", "full_name": "Global X Uranium ETF", "theme": "Uranium / nuclear", "region": "Global", "uranium": 1.0, "energy": .5, "geopolitical_sensitivity": .8},\n        {"asset": "LIT", "full_name": "Global X Lithium & Battery Tech ETF", "theme": "Battery materials", "region": "Global", "battery": 1.0, "nickel": .4, "china_sensitivity": .7},\n        {"asset": "REMX", "full_name": "VanEck Rare Earth/Strategic Metals ETF", "theme": "Rare earths", "region": "Global", "rare_earths": 1.0, "defense": .6, "geopolitical_sensitivity": .9},\n    ]\n    return pd.DataFrame(base)\n\nmaterials_cfg = normalize_materials(load_yaml("config/materials_universe.yml", {"materials": DEFAULT_MATERIALS}))\nmacro_cfg = normalize_macro(load_yaml("config/macro_series_config.yml", {"macro_proxies": DEFAULT_MACRO}))\nindices_cfg = normalize_indices(load_yaml("config/global_index_config.yml", {"indices": DEFAULT_INDICES}))\ngeo_cfg = load_yaml("config/geopolitical_keywords.yml", {"default_terms": DEFAULT_GEO_TERMS, "themes": {}})\nnews_sources = load_yaml("config/news_sources.yml", {"rss_sources": {}}).get("rss_sources", {})\nexposure = load_csv("data/exposure_score_table.csv", fallback_exposure())\ncompany_universe = load_csv("data/manufacturing_company_universe.csv", pd.DataFrame())\n\n# -----------------------------------------------------------------------------\n# Core mechanics\n# -----------------------------------------------------------------------------\ndef material_tickers(materials):\n    out = []\n    for spec in materials.values():\n        ticks = spec.get("tickers", [spec.get("ticker")]) if isinstance(spec, dict) else [str(spec)]\n        out += [t for t in ticks if isinstance(t, str) and t.strip()]\n    return out\n\ndef flatten_indices(idx):\n    rows = []\n    for region, mp in idx.items():\n        if isinstance(mp, dict):\n            for name, ticker in mp.items():\n                rows.append({"region": region, "name": name, "ticker": ticker})\n    return pd.DataFrame(rows)\n\ndef universal_period(interval, requested):\n    if interval == "1m":\n        return requested if requested in ["1d", "5d"] else "5d"\n    if interval in ["2m", "5m", "15m", "30m", "60m", "90m"]:\n        return requested if requested in ["1d", "5d", "1mo", "3mo", "6mo"] else "60d"\n    return requested\n\ndef adaptive_shock_window(n_rows, requested):\n    if n_rows < 20:\n        return max(2, n_rows // 4)\n    if n_rows < 80:\n        return max(3, min(requested, n_rows // 5))\n    if n_rows < 250:\n        return max(5, min(requested, n_rows // 8))\n    return max(5, min(requested, 100))\n\ndef interval_delta(interval, horizon):\n    if interval.endswith("m"):\n        return dt.timedelta(minutes=int(interval[:-1]) * horizon)\n    return dt.timedelta(days=horizon)\n\ndef valid_until(last_idx, interval, horizon):\n    try:\n        return pd.Timestamp(last_idx) + interval_delta(interval, horizon)\n    except Exception:\n        return "next horizon window"\n\n@st.cache_data(ttl=20, show_spinner=False)\ndef download_prices(tickers, period, interval):\n    tickers = sorted(set([t for t in tickers if isinstance(t, str) and t.strip()]))\n    if not tickers:\n        return pd.DataFrame()\n    raw = yf.download(tickers, period=period, interval=interval, auto_adjust=True, progress=False, threads=False)\n    if raw.empty:\n        return pd.DataFrame()\n    if isinstance(raw.columns, pd.MultiIndex):\n        pxs = raw["Close"].copy() if "Close" in raw.columns.get_level_values(0) else raw.xs("Close", axis=1, level=1, drop_level=True).copy()\n    else:\n        pxs = raw[["Close"]].copy()\n        if len(tickers) == 1:\n            pxs.columns = tickers\n    return pxs.dropna(axis=1, how="all").ffill().dropna(how="all")\n\ndef zscore(s, window):\n    window = max(2, int(window))\n    mean = s.rolling(window, min_periods=max(2, window // 3)).mean()\n    std = s.rolling(window, min_periods=max(2, window // 3)).std()\n    return ((s - mean) / std).replace([np.inf, -np.inf], np.nan)\n\ndef resolve_materials(prices, materials):\n    rows, resolved = [], {}\n    for name, spec in materials.items():\n        ticks = spec.get("tickers", [spec.get("ticker")]) if isinstance(spec, dict) else [str(spec)]\n        selected = next((t for t in ticks if t in prices.columns), None)\n        if selected:\n            resolved[name] = selected\n        rows.append({\n            "material": name,\n            "long_name": spec.get("long_name", name) if isinstance(spec, dict) else name,\n            "selected_ticker": selected or "missing",\n            "candidate_tickers": ", ".join([str(t) for t in ticks if t]),\n            "family": spec.get("family", "material") if isinstance(spec, dict) else "material",\n            "role": spec.get("role", "") if isinstance(spec, dict) else "",\n            "weight": float(spec.get("weight", .03)) if isinstance(spec, dict) else .03,\n        })\n    return resolved, pd.DataFrame(rows)\n\ndef build_features(prices, materials, macro, shock_window):\n    n = len(prices)\n    shock = adaptive_shock_window(n, shock_window)\n    f = pd.DataFrame(index=prices.index)\n    meta = []\n    resolved, proxy_table = resolve_materials(prices, materials)\n\n    pct_lag = max(1, min(shock, max(1, n // 4)))\n    for name, ticker in resolved.items():\n        spec = materials.get(name, {})\n        col = f"material:{name}"\n        f[col] = zscore(prices[ticker].pct_change(pct_lag), shock)\n        meta.append({"feature": col, "long_name": spec.get("long_name", name), "ticker": ticker, "family": spec.get("family", "material"), "weight": float(spec.get("weight", .03)), "definition": spec.get("role", "")})\n\n    for name, ticker in macro.items():\n        if ticker in prices.columns:\n            col = f"macro:{name}"\n            f[col] = zscore(prices[ticker].pct_change(pct_lag), shock)\n            meta.append({"feature": col, "long_name": name, "ticker": ticker, "family": "macro", "weight": .04, "definition": "macro or market-stress proxy"})\n\n    # Fallback: keep the workbench usable even when futures/material configs fail.\n    valid_cols = [c for c in f.columns if f[c].notna().sum() >= max(3, min(20, n // 5))]\n    if len(valid_cols) == 0:\n        for ticker in prices.columns[:50]:\n            px = prices[ticker].dropna()\n            if len(px) >= 8:\n                col = f"price:{ticker}"\n                local = max(2, min(shock, max(2, len(px) // 3)))\n                f[col] = zscore(prices[ticker].pct_change(max(1, min(local, len(px) // 4))), local)\n                meta.append({"feature": col, "long_name": f"Fallback price feature for {ticker}", "ticker": ticker, "family": "fallback_price", "weight": .02, "definition": "auto-built from downloaded prices when material features are insufficient"})\n\n    f = f.dropna(axis=1, how="all")\n    if f.empty:\n        return f, pd.DataFrame(meta), proxy_table, shock, "No usable features."\n\n    meta_df = pd.DataFrame(meta)\n    feature_cols = [c for c in f.columns if c in set(meta_df.get("feature", []))]\n    if feature_cols:\n        weights = {r["feature"]: float(r.get("weight", .02)) for _, r in meta_df.iterrows()}\n        weighted, denom = [], 0\n        for c in feature_cols:\n            w = weights.get(c, .02)\n            weighted.append(f[c].fillna(0) * w)\n            denom += w\n        f["GCMSI"] = sum(weighted) / denom if denom else f[feature_cols].mean(axis=1)\n    else:\n        f["GCMSI"] = f.mean(axis=1)\n\n    if not meta_df.empty and "family" in meta_df:\n        for fam in sorted(meta_df["family"].dropna().unique()):\n            cols = meta_df.loc[meta_df["family"] == fam, "feature"].tolist()\n            cols = [c for c in cols if c in f.columns]\n            if cols:\n                f[f"family:{fam}"] = f[cols].mean(axis=1)\n\n    if "macro:VIX" in f.columns:\n        f["regime:risk_off"] = (f["GCMSI"].fillna(0) + f["macro:VIX"].fillna(0)) / 2\n    if "macro:USDIndex" in f.columns:\n        f["regime:usd_pressure"] = (f["GCMSI"].fillna(0) + f["macro:USDIndex"].fillna(0)) / 2\n\n    f = f.replace([np.inf, -np.inf], np.nan).dropna(how="all")\n    if len(f) < 5:\n        return pd.DataFrame(), meta_df, proxy_table, shock, "Feature table too short after cleaning."\n    return f, meta_df, proxy_table, shock, "usable"\n\n# -----------------------------------------------------------------------------\n# Visuals\n# -----------------------------------------------------------------------------\ndef plot_lines(df, title, ytitle="value", normalize=False, height=440):\n    if df.empty:\n        st.warning("No data for this chart.")\n        return\n    x = df.copy().ffill().dropna(how="all")\n    if normalize and len(x):\n        x = x / x.iloc[0]\n    fig = go.Figure()\n    for col in x.columns:\n        fig.add_trace(go.Scatter(x=x.index, y=x[col], mode="lines", name=str(col), hovertemplate=f"{col}<br>%{{x}}<br>%{{y:.4f}}<extra></extra>"))\n    fig.update_layout(title=title, xaxis_title="time", yaxis_title=ytitle, legend_title="series", hovermode="x unified", height=height, margin=dict(l=30, r=30, t=60, b=30))\n    st.plotly_chart(fig, use_container_width=True)\n\ndef plot_bar(series, title, height=None):\n    if series.empty:\n        st.warning("No data for this chart.")\n        return\n    s = series.dropna().sort_values()\n    fig = px.bar(x=s.values, y=s.index, orientation="h", title=title, labels={"x": "score", "y": "item"})\n    fig.update_layout(height=height or max(380, 24 * len(s)), margin=dict(l=30, r=30, t=60, b=30))\n    st.plotly_chart(fig, use_container_width=True)\n\ndef read_block(title, body):\n    with st.expander(title, expanded=True):\n        st.markdown(body)\n\n# -----------------------------------------------------------------------------\n# News\n# -----------------------------------------------------------------------------\n@st.cache_data(ttl=240, show_spinner=False)\ndef gdelt(query, max_records):\n    try:\n        r = requests.get("https://api.gdeltproject.org/api/v2/doc/doc", params={"query": query, "mode": "ArtList", "format": "json", "maxrecords": max_records, "sort": "HybridRel"}, timeout=12)\n        if r.status_code != 200:\n            return pd.DataFrame()\n        return pd.DataFrame([{"title": a.get("title", ""), "source": "GDELT / " + a.get("domain", ""), "country": a.get("sourceCountry", ""), "date": a.get("seendate", ""), "url": a.get("url", ""), "source_type": "GDELT"} for a in r.json().get("articles", [])])\n    except Exception:\n        return pd.DataFrame()\n\n@st.cache_data(ttl=600, show_spinner=False)\ndef google_news_rss(query, max_records=40):\n    try:\n        url = "https://news.google.com/rss/search?q=" + quote_plus(query) + "&hl=en-US&gl=US&ceid=US:en"\n        r = requests.get(url, timeout=10, headers={"User-Agent": "MatQuantLab/1.0"})\n        if r.status_code != 200:\n            return pd.DataFrame()\n        root = ET.fromstring(r.content)\n        rows = []\n        for it in root.findall(".//item")[:max_records]:\n            rows.append({"title": (it.findtext("title") or "").strip(), "source": "Google News RSS", "country": "", "date": (it.findtext("pubDate") or "").strip(), "url": (it.findtext("link") or "").strip(), "source_type": "Google News RSS"})\n        return pd.DataFrame(rows)\n    except Exception:\n        return pd.DataFrame()\n\n@st.cache_data(ttl=900, show_spinner=False)\ndef rss_fetch(sources, max_per=10):\n    rows, status = [], []\n    for name, spec in sources.items():\n        url = spec.get("url", "") if isinstance(spec, dict) else str(spec)\n        focus = spec.get("focus", "") if isinstance(spec, dict) else ""\n        ok, count = False, 0\n        try:\n            r = requests.get(url, timeout=10, headers={"User-Agent": "MatQuantLab/1.0"})\n            if r.status_code == 200:\n                root = ET.fromstring(r.content)\n                items = root.findall(".//item")[:max_per]\n                ok, count = True, len(items)\n                for it in items:\n                    rows.append({"title": (it.findtext("title") or "").strip(), "source": name, "country": "", "date": (it.findtext("pubDate") or "").strip(), "url": (it.findtext("link") or "").strip(), "focus": focus, "source_type": "RSS"})\n        except Exception:\n            ok = False\n        status.append({"source": name, "url": url, "focus": focus, "ok": ok, "articles_loaded": count})\n    return pd.DataFrame(rows), pd.DataFrame(status)\n\ndef make_query(terms):\n    clean = [x.strip() for x in terms if x.strip()]\n    return "(" + " OR ".join(clean) + ")" if clean else "(critical minerals OR rare earth OR oil OR gas OR powder metallurgy)"\n\ndef score_news(news):\n    if news.empty:\n        return 0.0, pd.DataFrame()\n    themes = geo_cfg.get("themes", {})\n    if not themes:\n        themes = {\n            "war_conflict": {"long_name": "War and conflict", "weight": 1.6, "words": ["war", "conflict", "missile", "drone", "air strike"]},\n            "middle_east_iran": {"long_name": "Middle East, Iran and Hormuz", "weight": 1.8, "words": ["iran", "middle east", "hormuz", "red sea", "houthis"]},\n            "energy": {"long_name": "Fuel, gas and energy security", "weight": 1.3, "words": ["oil", "fuel", "gas", "lng", "opec", "uranium"]},\n            "critical_minerals": {"long_name": "Critical minerals and raw materials", "weight": 1.3, "words": ["critical minerals", "rare earth", "lithium", "cobalt", "nickel", "graphite", "titanium"]},\n            "am_pm": {"long_name": "Additive manufacturing and powder metallurgy", "weight": 1.2, "words": ["additive manufacturing", "3d printing", "powder metallurgy", "metal powder", "hip", "lpbf", "ebm"]},\n            "precious": {"long_name": "Gold, silver and safe-haven metals", "weight": 1.0, "words": ["gold", "silver", "safe haven", "bullion"]},\n        }\n    titles = " ".join(news["title"].fillna("").astype(str)).lower()\n    rows, score = [], 0\n    for theme, spec in themes.items():\n        words = spec.get("words", []) if isinstance(spec, dict) else spec\n        weight = float(spec.get("weight", 1)) if isinstance(spec, dict) else 1\n        long_name = spec.get("long_name", theme) if isinstance(spec, dict) else theme\n        count = sum(titles.count(str(w).lower()) for w in words)\n        rows.append({"theme": theme, "long_name": long_name, "mentions": count, "weighted_score": count * weight})\n        score += count * weight\n    return min(score / 14, 4.0), pd.DataFrame(rows).sort_values("weighted_score", ascending=False)\n\n# -----------------------------------------------------------------------------\n# ML\n# -----------------------------------------------------------------------------\ndef model_candidates():\n    return {\n        "Ridge": Ridge(alpha=8),\n        "ElasticNet": ElasticNet(alpha=.01, l1_ratio=.2, random_state=42),\n        "Huber": HuberRegressor(epsilon=1.35, alpha=.0001),\n        "RandomForest": RandomForestRegressor(n_estimators=180, max_depth=5, random_state=42),\n        "ExtraTrees": ExtraTreesRegressor(n_estimators=220, max_depth=5, random_state=42),\n        "GradientBoosting": GradientBoostingRegressor(random_state=42, max_depth=3),\n        "Blended": VotingRegressor([\n            ("ridge", Ridge(alpha=8)),\n            ("rf", RandomForestRegressor(n_estimators=120, max_depth=4, random_state=42)),\n            ("gb", GradientBoostingRegressor(random_state=42, max_depth=2)),\n        ])\n    }\n\ndef fit_eval(model, Xtr, ytr, Xte, yte):\n    model.fit(Xtr, ytr)\n    pred = model.predict(Xte)\n    corr = pd.Series(pred).corr(pd.Series(yte.values))\n    corr = 0 if pd.isna(corr) else float(corr)\n    rmse = float(mean_squared_error(yte, pred) ** .5)\n    vol = max(float(ytr.std()), 1e-6)\n    score = corr - 0.10 * min(rmse / vol, 5)\n    return model, pred, corr, rmse, score\n\ndef feature_importance(model, feat_cols):\n    if hasattr(model, "feature_importances_"):\n        return pd.Series(model.feature_importances_, index=feat_cols).sort_values(ascending=False)\n    if hasattr(model, "coef_"):\n        coef = np.array(model.coef_).reshape(-1)\n        return pd.Series(np.abs(coef), index=feat_cols[:len(coef)]).sort_values(ascending=False)\n    if hasattr(model, "estimators_"):\n        parts = []\n        for est in model.estimators_:\n            if hasattr(est, "feature_importances_"):\n                parts.append(pd.Series(est.feature_importances_, index=feat_cols))\n            elif hasattr(est, "coef_"):\n                coef = np.array(est.coef_).reshape(-1)\n                parts.append(pd.Series(np.abs(coef), index=feat_cols[:len(coef)]))\n        if parts:\n            return pd.concat(parts, axis=1).mean(axis=1).sort_values(ascending=False)\n    return pd.Series(0, index=feat_cols)\n\ndef validation_grade(conf, corr, test_rows):\n    if test_rows < 5:\n        return "low — too few test observations"\n    if corr > .10 and conf > .50:\n        return "high"\n    if corr > .03 and conf > .33:\n        return "medium"\n    if corr > 0:\n        return "low but positive"\n    return "low"\n\ndef research_stance(signal, conf, corr, test_rows):\n    grade = validation_grade(conf, corr, test_rows)\n    if signal == "positive" and conf >= .60 and grade in ["high", "medium"]:\n        return "positive pressure"\n    if signal == "negative" and conf >= .60 and grade in ["high", "medium"]:\n        return "negative pressure"\n    if signal == "positive" and conf >= .33 and corr > -0.02:\n        return "mild positive pressure"\n    if signal == "negative" and conf >= .33 and corr > -0.02:\n        return "risk watch"\n    return "no reliable signal"\n\ndef train_one(asset, prices, features, requested_horizon, model_name, feat_cols, interval):\n    if asset not in prices.columns:\n        return None, None, "no price"\n    px = prices[asset].dropna()\n    if len(px) < 12:\n        return None, None, "not enough price rows"\n\n    n = min(len(px), len(features))\n    effective_horizon = max(1, min(int(requested_horizon), max(1, n // 8)))\n\n    def dataset(h):\n        y = prices[asset].pct_change(h).shift(-h).rename("future_return")\n        X = features[feat_cols].copy()\n        return pd.concat([X, y], axis=1, join="inner").dropna(subset=["future_return"])\n\n    df = dataset(effective_horizon)\n    if len(df) < 25:\n        effective_horizon = max(1, min(5, requested_horizon))\n        df = dataset(effective_horizon)\n    if len(df) < 16:\n        effective_horizon = 1\n        df = dataset(1)\n    if len(df) < 12:\n        return None, None, "not enough rows"\n\n    df[feat_cols] = df[feat_cols].fillna(0)\n    split = max(8, int(len(df) * .70))\n    if split >= len(df) - 3:\n        split = max(6, len(df) - 4)\n    tr, te = df.iloc[:split], df.iloc[split:]\n    if len(te) < 2:\n        return None, None, "too few test rows"\n\n    Xtr, ytr = tr[feat_cols], tr["future_return"].astype(float)\n    Xte, yte = te[feat_cols], te["future_return"].astype(float)\n\n    candidates = model_candidates()\n    if model_name == "Adaptive":\n        best = None\n        for nm, model in candidates.items():\n            try:\n                m, pred, corr, rmse, score = fit_eval(model, Xtr, ytr, Xte, yte)\n                if best is None or score > best["score"]:\n                    best = {"name": nm, "model": m, "pred": pred, "corr": corr, "rmse": rmse, "score": score}\n            except Exception:\n                pass\n        if best is None:\n            return None, None, "models failed"\n        selected_model = best["name"]\n        model, pred, corr, rmse = best["model"], best["pred"], best["corr"], best["rmse"]\n    else:\n        try:\n            model, pred, corr, rmse, _ = fit_eval(candidates.get(model_name, Ridge(alpha=8)), Xtr, ytr, Xte, yte)\n            selected_model = model_name\n        except Exception:\n            return None, None, "model failed"\n\n    latest_pred = float(model.predict(features.iloc[[-1]][feat_cols].fillna(0))[0])\n    vol = max(float(ytr.std()), 1e-6)\n    conf = min(abs(latest_pred) / (vol * 1.25), 1)\n    sig = "positive" if latest_pred > 0 else "negative"\n    strength = "strong" if conf > .66 else "moderate" if conf > .33 else "weak"\n    trust = validation_grade(conf, corr, len(te))\n    stance = research_stance(sig, conf, corr, len(te))\n\n    imp = feature_importance(model, feat_cols)\n    d1 = imp.index[0] if len(imp) > 0 else ""\n    d2 = imp.index[1] if len(imp) > 1 else ""\n    d3 = imp.index[2] if len(imp) > 2 else ""\n\n    te2 = te.copy()\n    te2["prediction"] = pred\n    te2["position"] = np.where(te2["prediction"] > 0, 1, -1)\n    te2["strategy_return_net"] = te2["position"] * te2["future_return"] - .0005 * pd.Series(te2["position"], index=te2.index).diff().abs().fillna(1)\n    te2["equity_net"] = (1 + te2["strategy_return_net"].fillna(0)).cumprod()\n    dd = float((te2["equity_net"] / te2["equity_net"].cummax() - 1).min()) if len(te2) else 0\n\n    vu = valid_until(px.index[-1], interval, effective_horizon)\n    vu_str = str(vu)\n    first_date, last_date = str(pd.Timestamp(df.index[0])), str(pd.Timestamp(df.index[-1]))\n\n    reason = f"{selected_model} estimates {sig} pressure over {effective_horizon} {interval} bars. The leading model inputs are {d1}, {d2}, and {d3}."\n    final_message = f"{stance}. Research horizon: until approximately {vu_str}. Data used: {first_date} to {last_date}. Trust level: {trust}; test correlation {corr:.3f}; signal strength {strength}. {reason}"\n\n    row = {\n        "asset": asset,\n        "model": selected_model,\n        "signal": sig,\n        "stance": stance,\n        "strength": strength,\n        "trust": trust,\n        "prediction": latest_pred,\n        "confidence": conf,\n        "test_corr": corr,\n        "rmse": rmse,\n        "drawdown_check": dd,\n        "requested_horizon": requested_horizon,\n        "effective_horizon": effective_horizon,\n        "valid_until": vu_str,\n        "data_start": first_date,\n        "data_end": last_date,\n        "train_rows": len(tr),\n        "test_rows": len(te),\n        "driver_1": d1,\n        "driver_2": d2,\n        "driver_3": d3,\n        "reason": reason,\n        "message": final_message,\n    }\n    return row, te2, None\n\n@st.cache_data(ttl=120, show_spinner=False)\ndef options_chain(ticker, expiry=None):\n    try:\n        tk = yf.Ticker(ticker)\n        expiries = list(tk.options)\n        if not expiries:\n            return expiries, pd.DataFrame(), pd.DataFrame()\n        exp = expiry if expiry in expiries else expiries[0]\n        ch = tk.option_chain(exp)\n        return expiries, ch.calls.copy(), ch.puts.copy()\n    except Exception:\n        return [], pd.DataFrame(), pd.DataFrame()\n\n# -----------------------------------------------------------------------------\n# Domain-specific calculations\n# -----------------------------------------------------------------------------\ndef current_value(features, keys):\n    vals = []\n    latest = features.iloc[-1]\n    for k in keys:\n        if k in latest and pd.notna(latest[k]):\n            vals.append(float(latest[k]))\n    return float(np.mean(vals)) if vals else 0.0\n\ndef compute_am_pm(features):\n    cols = {\n        "AM powder feedstock": ["material:Titanium", "material:Nickel", "material:Aluminum", "family:aerospace_defense_materials"],\n        "Powder metallurgy input cost": ["family:steel_chain", "material:NaturalGas", "material:Graphite", "family:energy_inputs"],\n        "Aerospace / defense demand": ["family:aerospace_defense_materials", "material:Titanium", "family:rare_earths"],\n        "Energy and process cost": ["family:energy_inputs", "material:NaturalGas", "material:Oil"],\n        "Risk appetite": ["macro:VIX", "regime:risk_off", "GCMSI"],\n    }\n    out = pd.DataFrame(index=features.index)\n    for name, keys in cols.items():\n        available = [k for k in keys if k in features.columns]\n        if available:\n            out[name] = features[available].mean(axis=1)\n    if not out.empty:\n        out["AM / PM stress basket"] = out.mean(axis=1)\n    return out\n\ndef transmission_scores(exposure_df, features, gscore):\n    latest = features.iloc[-1]\n    stress_map = {\n        "copper": latest.get("material:Copper", 0),\n        "aluminum": latest.get("material:Aluminum", 0),\n        "nickel": latest.get("material:Nickel", 0),\n        "steel_chain": latest.get("family:steel_chain", 0),\n        "battery": latest.get("family:battery_materials", 0),\n        "rare_earths": latest.get("family:rare_earths", 0),\n        "energy": latest.get("family:energy_inputs", 0),\n        "coal": latest.get("material:CokingCoal", 0) + latest.get("material:ThermalCoal", 0),\n        "uranium": latest.get("material:Uranium", 0),\n        "aerospace": latest.get("family:aerospace_defense_materials", 0),\n        "defense": gscore,\n        "semiconductor": latest.get("family:rare_earths", 0) + latest.get("macro:Semiconductors", 0),\n        "additive_manufacturing": current_value(features, ["material:Titanium", "material:Nickel", "material:Aluminum", "family:energy_inputs"]),\n        "china_sensitivity": latest.get("macro:USDCNY", 0),\n        "geopolitical_sensitivity": gscore,\n        "macro_beta": latest.get("family:macro", 0),\n    }\n    rows = []\n    for _, r in exposure_df.iterrows():\n        total, den = 0, 0\n        leading = []\n        for k, stress in stress_map.items():\n            if k in r and pd.notna(r[k]):\n                exp = float(r[k])\n                contrib = exp * float(stress)\n                total += contrib\n                den += abs(exp)\n                if abs(contrib) > 0:\n                    leading.append((k, contrib))\n        leading = sorted(leading, key=lambda x: abs(x[1]), reverse=True)[:3]\n        rows.append({\n            "asset": r.get("asset", ""),\n            "name": r.get("full_name", ""),\n            "theme": r.get("theme", ""),\n            "region": r.get("region", ""),\n            "transmission_score": total / den if den else 0,\n            "main_transmission_path": " → ".join([x[0] for x in leading]) if leading else "not mapped",\n        })\n    return pd.DataFrame(rows).sort_values("transmission_score", ascending=False)\n\ndef contradictions(features, pred, gscore):\n    latest = features.iloc[-1]\n    rows = []\n    def add(title, why, severity):\n        rows.append({"contradiction": title, "why it matters": why, "severity": severity})\n    copper = latest.get("material:Copper", np.nan)\n    gold = latest.get("material:Gold", np.nan)\n    vix = latest.get("macro:VIX", np.nan)\n    rare = latest.get("family:rare_earths", np.nan)\n    energy = latest.get("family:energy_inputs", np.nan)\n    gc = latest.get("GCMSI", 0)\n\n    if gscore > 2 and abs(gc) < .5:\n        add("News risk is high but market stress is not extreme", "Policy/geopolitical headlines are active, but pricing has not fully confirmed stress yet.", "medium")\n    if pd.notna(vix) and pd.notna(gold) and vix > .8 and gold < 0:\n        add("Volatility is rising while gold is not confirming", "Risk appetite is weakening, but safe-haven metals are not confirming the same message.", "medium")\n    if pd.notna(copper) and copper < -.8 and not pred.empty and "COPX" in pred["asset"].values:\n        copx = pred.loc[pred["asset"] == "COPX"].iloc[0]\n        if copx["signal"] == "positive":\n            add("Copper weak, copper miners positive", "Equity signal is stronger than the material signal; this may be momentum, lag, or model instability.", "high")\n    if pd.notna(rare) and rare > .8 and not pred.empty and "REMX" in pred["asset"].values:\n        remx = pred.loc[pred["asset"] == "REMX"].iloc[0]\n        if remx["signal"] == "negative":\n            add("Rare-earth stress high, rare-earth equity proxy negative", "Material stress and equity signal disagree; check news/policy and validation.", "high")\n    if pd.notna(energy) and energy > 1 and not pred.empty:\n        exposed = pred[pred.get("asset", pd.Series(dtype=str)).isin(["ITA", "XAR", "AIR.PA", "SAF.PA", "BA", "GE", "RR.L"])]\n        if not exposed.empty and (exposed["signal"] == "positive").any():\n            add("Energy cost stress high while aerospace signals are positive", "Possible demand strength is offsetting fuel/process-cost pressure, or the energy shock is not yet transmitted.", "medium")\n    if not rows:\n        add("No major contradiction detected", "The current stress, news and model layers are not showing a clear conflict under the simple rules.", "low")\n    return pd.DataFrame(rows)\n\ndef regime(latest, gscore):\n    gc = latest.get("GCMSI", 0)\n    vix = latest.get("macro:VIX", 0)\n    usd = latest.get("macro:USDIndex", 0)\n    energy = latest.get("family:energy_inputs", 0)\n    if gscore >= 2.5 and gc > .4:\n        return "geopolitical material-risk regime"\n    if gc > 1.2 and vix > .8:\n        return "industrial risk-off"\n    if energy > 1.1:\n        return "energy-cost pressure"\n    if usd > 1.0 and gc > .3:\n        return "USD and commodity pressure"\n    if gc > .8:\n        return "commodity stress"\n    if gc < -.8:\n        return "stress easing"\n    return "mixed / normal"\n\ndef brief_text(reg, gscore, latest, pred, contradictions_df):\n    gc = latest.get("GCMSI", 0)\n    direction = "elevated" if gc > .8 else "easing" if gc < -.8 else "mixed"\n    top_signal = "no strong signal"\n    if not pred.empty:\n        top = pred.sort_values("confidence", ascending=False).iloc[0]\n        top_signal = f"{top[\'asset\']} shows {top[\'stance\']} with {top[\'trust\']} trust"\n    contra = contradictions_df.iloc[0]["contradiction"] if not contradictions_df.empty else "no major contradiction"\n    return (\n        f"Current material stress is {direction}. The regime reads as **{reg}**. "\n        f"News/event risk score is **{gscore:.2f}**. The strongest model output is: **{top_signal}**. "\n        f"Main system tension: **{contra}**."\n    )\n\n# -----------------------------------------------------------------------------\n# App layout\n# -----------------------------------------------------------------------------\nst.set_page_config(page_title="MatQuantLab", layout="wide")\nst.title(UI_TEXT["product_title"])\nst.subheader(UI_TEXT["subtitle"])\nst.caption(UI_TEXT["description"])\n\nidx_df = flatten_indices(indices_cfg)\ncore_assets = sorted(set(exposure["asset"].astype(str).tolist() + ["SPY", "XME", "COPX", "ITA", "XAR", "PRNT", "SOXX", "XLE", "URA", "LIT", "REMX", "SLX", "GLD", "SLV", "USO", "UNG"]))\ncompany_assets = sorted(company_universe["ticker"].dropna().astype(str).unique().tolist()) if not company_universe.empty else []\nfuture_assets = sorted(set(FUTURES_UNIVERSE.values()))\nall_assets = sorted(set(core_assets + company_assets + future_assets))\ndefault_assets = [x for x in ["SPY", "COPX", "XME", "ITA", "XAR", "PRNT", "GLD", "SLV", "USO", "URA", "LIT", "REMX"] if x in all_assets]\n\nwith st.sidebar:\n    st.header("Research setup")\n    st.caption("Choose the universe, time scale and model style. Daily multi-year data gives the most stable signals; intraday is for monitoring.")\n\n    asset_mode = st.radio("Universe", ["Core assets", "Manufacturing companies", "Commodities and futures", "Everything"], index=3)\n    country_filter = []\n    if not company_universe.empty:\n        country_filter = st.multiselect("Manufacturing countries", sorted(company_universe["country"].dropna().unique().tolist()), default=[])\n\n    if asset_mode == "Core assets":\n        choices = core_assets\n    elif asset_mode == "Manufacturing companies":\n        choices = company_assets\n    elif asset_mode == "Commodities and futures":\n        choices = future_assets\n    else:\n        choices = all_assets\n\n    if country_filter and not company_universe.empty:\n        country_tickers = company_universe.loc[company_universe["country"].isin(country_filter), "ticker"].astype(str).tolist()\n        if asset_mode == "Manufacturing companies":\n            choices = sorted(set(country_tickers))\n        elif asset_mode == "Everything":\n            choices = sorted(set(core_assets + future_assets + country_tickers))\n\n    assets = st.multiselect("Assets to evaluate", choices, default=[x for x in default_assets if x in choices][:12])\n    interval = st.selectbox("Data interval", ["1m", "5m", "15m", "30m", "60m", "1d"], index=5)\n    period = st.selectbox("History", ["1d", "5d", "1mo", "3mo", "6mo", "1y", "2y", "5y", "10y"], index=7)\n    model_name = st.selectbox("Model selection", ["Adaptive", "Ridge", "ElasticNet", "Huber", "RandomForest", "ExtraTrees", "GradientBoosting", "Blended"], index=0)\n    horizon = st.slider("Research horizon, in bars", 1, 120, 10)\n    shock_window = st.slider("Shock window, in bars", 2, 150, 20)\n    max_news = st.slider("News rows", 10, 150, 80)\n\n    terms = st.multiselect(\n        "Event terms",\n        sorted(set(DEFAULT_GEO_TERMS + geo_cfg.get("default_terms", []) + ["AM powder", "powder metallurgy", "LPBF", "EBM", "HIP", "metal powder", "titanium powder", "nickel powder", "aerospace backlog", "defense procurement"])),\n        default=geo_cfg.get("default_terms", DEFAULT_GEO_TERMS)[:24] if isinstance(geo_cfg.get("default_terms", DEFAULT_GEO_TERMS), list) else DEFAULT_GEO_TERMS\n    )\n    extra = st.text_input("Extra event terms, comma separated", value="")\n    if extra:\n        terms += [x.strip() for x in extra.split(",") if x.strip()]\n\n    auto = st.toggle("Auto-refresh", value=False)\n    seconds = st.selectbox("Refresh every", [20, 30, 60, 120, 300], index=2)\n    if st.button("Refresh now"):\n        st.cache_data.clear()\n        st.rerun()\n\nif auto:\n    time.sleep(seconds)\n    st.cache_data.clear()\n    st.rerun()\n\nactual_period = universal_period(interval, period)\nquery = make_query(terms)\ntickers = sorted(set(assets + material_tickers(materials_cfg) + list(macro_cfg.values()) + idx_df.get("ticker", pd.Series(dtype=str)).dropna().tolist() + list(FUTURES_UNIVERSE.values())))\n\nprices = download_prices(tickers, actual_period, interval)\nif prices.empty:\n    st.error("No market data loaded. Try fewer assets, daily interval, or a shorter universe.")\n    st.stop()\n\nfeatures, meta, proxy_table, effective_shock, feature_status = build_features(prices, materials_cfg, macro_cfg, shock_window)\nif features.empty:\n    st.error("Feature construction failed even after fallback. Select SPY, GLD, USO or XME and use daily data.")\n    st.stop()\n\ngd = gdelt(query, max_news)\ngnews = google_news_rss(query, max_records=min(max_news, 50))\nrss, rss_status = rss_fetch(news_sources, max_per=10)\nnews = pd.concat([x for x in [gd, gnews, rss] if not x.empty], ignore_index=True) if (not gd.empty or not gnews.empty or not rss.empty) else pd.DataFrame()\ngscore, gthemes = score_news(news)\n\nlatest = features.iloc[-1]\nreg = regime(latest, gscore)\nfeat_cols = [c for c in features.columns if features[c].notna().sum() >= max(3, min(20, len(features) // 5))]\nif "GCMSI" not in feat_cols and "GCMSI" in features.columns:\n    feat_cols.append("GCMSI")\nfeat_cols = list(dict.fromkeys(feat_cols))\n\npred_rows, curves = [], {}\nfor a in assets:\n    row, curve, err = train_one(a, prices, features, horizon, model_name, feat_cols, interval)\n    if row:\n        exp = exposure.loc[exposure["asset"].astype(str) == a]\n        comp = company_universe.loc[company_universe["ticker"].astype(str) == a] if not company_universe.empty else pd.DataFrame()\n        if len(exp):\n            row["name"] = exp.iloc[0].get("full_name", "")\n            row["theme"] = exp.iloc[0].get("theme", "")\n            row["region"] = exp.iloc[0].get("region", "")\n            row["group"] = row["theme"]\n        if len(comp):\n            row["name"] = comp.iloc[0].get("company", row.get("name", ""))\n            row["theme"] = comp.iloc[0].get("material_link", row.get("theme", ""))\n            row["region"] = comp.iloc[0].get("country", row.get("region", ""))\n            row["group"] = comp.iloc[0].get("industry_group", "")\n        if not row.get("name"):\n            row["name"] = next((k for k, v in FUTURES_UNIVERSE.items() if v == a), a)\n            row["theme"] = "commodity / future / proxy"\n            row["region"] = "global"\n            row["group"] = "materials and macro"\n        pred_rows.append(row)\n        curves[a] = curve\n\npred = pd.DataFrame(pred_rows).sort_values(["confidence", "test_corr"], ascending=[False, False]) if pred_rows else pd.DataFrame()\ncontradictions_df = contradictions(features, pred, gscore)\nam_pm = compute_am_pm(features)\ntransmission = transmission_scores(exposure, features, gscore) if not exposure.empty else pd.DataFrame()\n\n# Top metrics\nm1, m2, m3, m4, m5, m6 = st.columns(6)\nm1.metric("Material stress", f"{latest.get(\'GCMSI\', 0):.2f}")\nm2.metric("Regime", reg)\nm3.metric("Event risk", f"{gscore:.2f}")\nm4.metric("Series loaded", prices.shape[1])\nm5.metric("Features", features.shape[1])\nm6.metric("Signals", len(pred))\n\nif actual_period != period:\n    st.warning(f"Requested {period} with {interval} data. The workbench used {actual_period}, which is more realistic for that interval.")\nst.caption(f"Market data coverage: {prices.index[0]} → {prices.index[-1]} | feature status: {feature_status} | effective shock window: {effective_shock}")\n\ntabs = st.tabs(["Brief", "Stress Monitor", "Exposure Map", "Signals", "News & Events", "Data Quality"])\n\n# -----------------------------------------------------------------------------\n# Brief\n# -----------------------------------------------------------------------------\nwith tabs[0]:\n    st.subheader("Market brief")\n    st.markdown(brief_text(reg, gscore, latest, pred, contradictions_df))\n    read_block("How to use this page", """\nThis page is meant to answer four questions before you look at detailed charts:\n\n1. **What is stressed?** Look at material stress, energy, precious metals and macro stress.\n2. **Why is it stressed?** Check the strongest drivers and news themes.\n3. **Who is exposed?** Use the exposure map and transmission scores.\n4. **Can the model be trusted?** Read the signal trust level and the data-quality panel.\n\nThe workbench does not try to be a trading bot. It is a materials-to-market research map.\n""")\n\n    c1, c2 = st.columns([1.1, 1])\n    with c1:\n        if not pred.empty:\n            summary_cols = ["asset", "name", "stance", "strength", "trust", "effective_horizon", "valid_until", "driver_1", "driver_2"]\n            st.markdown("### Current model signals")\n            st.dataframe(pred[summary_cols], use_container_width=True)\n        else:\n            st.info("No model signals were produced for the selected assets.")\n    with c2:\n        st.markdown("### Main system tensions")\n        st.dataframe(contradictions_df, use_container_width=True)\n\n    if not am_pm.empty:\n        st.markdown("### Additive manufacturing and powder metallurgy basket")\n        st.metric("AM / PM stress basket", f"{am_pm[\'AM / PM stress basket\'].iloc[-1]:.2f}")\n        read_block("What the AM / PM basket means", """\nThis basket is built around **metal powder and powder-processing economics**, not only 3D-printing stock prices.\n\nIt combines:\n- **Powder feedstock pressure:** titanium, nickel, aluminum and aerospace-material stress.\n- **Powder metallurgy input cost:** steel-chain, graphite, natural gas and process-energy pressure.\n- **Aerospace/defense demand:** demand channels where LPBF, EBM, DED, HIP and PM parts are most relevant.\n- **Energy and process cost:** gas, power, heat treatment, HIP and atomization-related cost pressure.\n- **Risk appetite:** whether industrial growth names are being rewarded or punished.\n\nPositive values mean the AM/PM environment is more stressed than usual. Negative values mean easing or lower pressure.\n""")\n\n# -----------------------------------------------------------------------------\n# Stress Monitor\n# -----------------------------------------------------------------------------\nwith tabs[1]:\n    st.subheader("Stress monitor")\n    radar_cols = [c for c in [\n        "GCMSI", "family:industrial_metals", "family:steel_chain", "family:battery_materials",\n        "family:rare_earths", "family:aerospace_defense_materials", "family:superalloys_battery_metals",\n        "family:energy_inputs", "family:energy_security", "family:precious_stress",\n        "family:precious_industrial", "family:macro", "family:fallback_price",\n        "regime:risk_off", "regime:usd_pressure"\n    ] if c in features.columns]\n    plot_lines(features[radar_cols], "Material, energy, precious-metal and macro stress", "z-score stress")\n    read_block("How to read the stress chart", """\nEach line is converted to a comparable **z-score** scale.\n\n- Around **0**: normal for that series.\n- Around **+1**: above-normal pressure or upward shock.\n- Around **+2**: unusually high pressure.\n- Around **-1 or -2**: easing, weakness or downside pressure.\n\nThe important part is not only whether a line is high or low; it is **which families move together**.  \nExample: energy stress rising together with aerospace-material stress can point toward margin pressure in aerospace supply chains.\n""")\n\n    drivers = latest[[c for c in features.columns if c != "GCMSI"]].sort_values(key=lambda s: s.abs(), ascending=False).head(35)\n    plot_bar(drivers, "Current strongest drivers")\n    read_block("How to read the driver chart", """\nThe bar chart shows the most unusual current inputs.\n\n- Bars to the **right** are positive shocks.\n- Bars to the **left** are negative/easing shocks.\n- The biggest bars are the inputs most likely to affect the brief, exposure map and model signals.\n\nIf the largest drivers are fallback price features, it means some direct material/future proxies were unavailable and the workbench used downloaded prices to keep the system running.\n""")\n\n    if not am_pm.empty:\n        st.markdown("### AM / powder metallurgy stress")\n        plot_lines(am_pm, "Additive manufacturing and powder metallurgy stress components", "z-score stress")\n        read_block("Technical reading: AM and powder metallurgy", """\nThis chart separates the AM/PM chain into interpretable components:\n\n- **AM powder feedstock:** titanium, nickel, aluminum and aerospace-material pressure.\n- **Powder metallurgy input cost:** steel-chain, graphite, natural gas and process-energy pressure.\n- **Aerospace / defense demand:** the demand channel for many high-value AM and PM parts.\n- **Energy and process cost:** atomization, heat treatment, HIP and high-temperature process sensitivity.\n- **Risk appetite:** whether markets are rewarding or punishing industrial growth exposure.\n\nThis is meant to connect metallurgy knowledge to market signals: powder feedstock, process energy, aerospace demand and risk appetite do not always move together.\n""")\n\n    st.markdown("### Commodity, future and proxy monitor")\n    fdf = pd.DataFrame([{"instrument": k, "ticker": v, "downloaded": v in prices.columns} for k, v in FUTURES_UNIVERSE.items()])\n    st.dataframe(fdf, use_container_width=True)\n    downloaded = [t for t in fdf.loc[fdf["downloaded"], "ticker"].tolist() if t in prices.columns]\n    selected_f = st.multiselect("Chart commodity/future/proxy series", downloaded, default=downloaded[:10])\n    if selected_f:\n        plot_lines(prices[selected_f], "Commodity and future proxies, normalized", "normalized price", normalize=True)\n        st.caption("Normalized chart starts every series at 1.0, so different units can be compared.")\n\n# -----------------------------------------------------------------------------\n# Exposure Map\n# -----------------------------------------------------------------------------\nwith tabs[2]:\n    st.subheader("Exposure map")\n    read_block("What the exposure map does", """\nThe exposure map is the materials-engineering layer.\n\nIt asks: **if a shock starts in a material or process input, which listed assets are most exposed?**\n\nExamples:\n- Natural gas shock → aluminum smelting and heat-treatment cost → aerospace and industrial margins.\n- Rare-earth export-control news → magnet supply risk → EV motors, defense electronics and semiconductor equipment.\n- Titanium/nickel pressure → aerospace alloys and AM powder feedstock → aerospace, defense and AM-linked assets.\n- Coking coal / iron ore shock → steel chain → machinery, autos, construction and powder metallurgy inputs.\n""")\n\n    if not exposure.empty:\n        st.markdown("### Asset exposure table")\n        st.dataframe(exposure, use_container_width=True)\n\n    st.markdown("### Exposure column definitions")\n    st.dataframe(pd.DataFrame([{"exposure": k, "meaning": v} for k, v in EXPOSURE_DEFS.items()]), use_container_width=True)\n\n    if not transmission.empty:\n        st.markdown("### Material transmission scores")\n        st.dataframe(transmission, use_container_width=True)\n        plot_bar(transmission.set_index("asset")["transmission_score"].head(25), "Highest current transmission scores")\n        read_block("How to read transmission scores", """\nTransmission score is not a price forecast. It is a stress-routing score.\n\nIt combines:\n1. the current material/macro/geopolitical stress level, and  \n2. the asset\'s exposure to that stress channel.\n\nA high score means an asset is sitting closer to the current shock pathway.  \nA negative score means the mapped inputs are easing or moving in the opposite direction.\n""")\n\n    st.markdown("### Manufacturing and materials company universe")\n    if company_universe.empty:\n        st.info("Manufacturing company universe file not found.")\n    else:\n        countries = st.multiselect("Filter company table by country", sorted(company_universe["country"].dropna().unique().tolist()), default=country_filter)\n        table = company_universe.copy()\n        if countries:\n            table = table[table["country"].isin(countries)]\n        st.dataframe(table, use_container_width=True)\n        counts = table.groupby("country")["ticker"].count().sort_values(ascending=False)\n        plot_bar(counts, "Companies by country in the current universe")\n        read_block("How to use the company universe", """\nThis table is not meant to be an index. It is a research universe of listed companies tied to materials, manufacturing and industrial supply chains.\n\nIt includes examples from mining, aerospace, defense, semiconductors, autos, machinery, energy, steel, chemicals, battery materials and additive manufacturing.  \nSome international tickers may not download at every interval. Daily data is usually more reliable than intraday data.\n""")\n\n# -----------------------------------------------------------------------------\n# Signals\n# -----------------------------------------------------------------------------\nwith tabs[3]:\n    st.subheader("Signals")\n    read_block("How to read signals", """\nThe signal table is intentionally conservative.\n\n- **Stance:** plain-language pressure label such as positive pressure, risk watch or no reliable signal.\n- **Strength:** how large the latest prediction is compared with historical volatility.\n- **Trust:** how usable the signal is based on out-of-sample correlation and test rows.\n- **Valid until:** estimated horizon based on interval × effective horizon.\n- **Drivers:** the model inputs most responsible for the signal.\n\nA signal with low trust should be treated as a diagnostic, not a conclusion.\n""")\n\n    if pred.empty:\n        st.warning("No signals were produced. Try daily data, longer history, fewer assets, or core assets.")\n    else:\n        signal_cols = ["asset", "name", "region", "group", "model", "stance", "signal", "strength", "trust", "prediction", "confidence", "test_corr", "driver_1", "driver_2", "driver_3", "effective_horizon", "valid_until", "data_start", "data_end", "message"]\n        st.dataframe(pred[signal_cols], use_container_width=True)\n        plot_bar(pred["stance"].value_counts(), "Signal stance distribution")\n\n        chosen = st.selectbox("Inspect one signal", pred["asset"].tolist())\n        row = pred[pred["asset"] == chosen].iloc[0]\n        st.markdown(f"### {chosen} — {row.get(\'name\', \'\')}")\n        a, b, c, d = st.columns(4)\n        a.metric("Stance", row["stance"])\n        b.metric("Trust", row["trust"])\n        c.metric("Test corr.", f"{row[\'test_corr\']:.3f}")\n        d.metric("Valid until", str(row["valid_until"])[:16])\n        st.markdown("**Interpretation**")\n        st.write(row["message"])\n        if chosen in curves:\n            plot_lines(curves[chosen][["prediction", "future_return"]], f"{chosen}: prediction vs realized future return", "return")\n            st.caption("If prediction and realized future return often move together, the model had some recent alignment. If not, reduce trust.")\n            plot_lines(curves[chosen][["equity_net"]], f"{chosen}: toy net curve with simple cost", "equity")\n            st.caption("This is a diagnostic curve only; it is not a production backtest.")\n\n    st.markdown("### Options context")\n    opt_asset = st.selectbox("Options ticker", assets if assets else ["SPY", "XME", "COPX", "GLD", "SLV", "USO"])\n    expiries, calls, puts = options_chain(opt_asset)\n    if not expiries:\n        st.info("No Yahoo options chain found for this ticker. Try SPY, XME, COPX, ITA, XLE, GLD, SLV or USO.")\n    else:\n        exp = st.selectbox("Expiration", expiries)\n        expiries, calls, puts = options_chain(opt_asset, exp)\n        cvol = calls["volume"].fillna(0).sum() if not calls.empty else 0\n        pvol = puts["volume"].fillna(0).sum() if not puts.empty else 0\n        coi = calls["openInterest"].fillna(0).sum() if not calls.empty else 0\n        poi = puts["openInterest"].fillna(0).sum() if not puts.empty else 0\n        o1, o2, o3, o4 = st.columns(4)\n        o1.metric("Call volume", int(cvol))\n        o2.metric("Put volume", int(pvol))\n        o3.metric("Put/Call volume", f"{pvol / max(cvol, 1):.2f}")\n        o4.metric("Put/Call open interest", f"{poi / max(coi, 1):.2f}")\n        read_block("How to read options context", """\nOptions are not used as the main model target here. They provide market-positioning context.\n\n- High put/call volume can indicate hedging or bearish demand.\n- High open interest shows where contracts remain outstanding.\n- Implied volatility gives the market\'s pricing of uncertainty.\n\nOptions should confirm or challenge the signal, not replace validation.\n""")\n        st.markdown("#### Calls")\n        st.dataframe(calls[["contractSymbol", "strike", "lastPrice", "bid", "ask", "volume", "openInterest", "impliedVolatility"]].sort_values("openInterest", ascending=False).head(50), use_container_width=True)\n        st.markdown("#### Puts")\n        st.dataframe(puts[["contractSymbol", "strike", "lastPrice", "bid", "ask", "volume", "openInterest", "impliedVolatility"]].sort_values("openInterest", ascending=False).head(50), use_container_width=True)\n\n# -----------------------------------------------------------------------------\n# News & Events\n# -----------------------------------------------------------------------------\nwith tabs[4]:\n    st.subheader("News and events")\n    st.caption("The news layer is a monitoring layer. It does not claim to understand full context; it routes headlines into material-risk themes.")\n    st.write(f"Search query: `{query}`")\n    n1, n2, n3 = st.columns(3)\n    n1.metric("Event risk score", f"{gscore:.2f}")\n    n2.metric("News rows", len(news))\n    n3.metric("Themes active", int((gthemes["mentions"] > 0).sum()) if not gthemes.empty else 0)\n\n    source_status = pd.DataFrame([\n        {"source": "GDELT", "ok": not gd.empty, "articles_loaded": len(gd), "focus": "global query news"},\n        {"source": "Google News RSS", "ok": not gnews.empty, "articles_loaded": len(gnews), "focus": "query news RSS"},\n    ])\n    if not rss_status.empty:\n        source_status = pd.concat([source_status, rss_status[["source", "ok", "articles_loaded", "focus"]]], ignore_index=True)\n    st.markdown("### Source status")\n    st.dataframe(source_status, use_container_width=True)\n\n    st.markdown("### Theme intensity")\n    if not gthemes.empty:\n        st.dataframe(gthemes, use_container_width=True)\n        plot_bar(gthemes.set_index("long_name")["weighted_score"], "Event theme intensity")\n    read_block("How to read the event themes", """\nThe event score is keyword-based. It is useful for monitoring, not for final judgment.\n\nTheme examples:\n- **Energy / fuel:** oil, gas, LNG, refinery, pipeline, uranium.\n- **Middle East / Iran / Hormuz:** possible fuel and shipping-risk transmission.\n- **Critical minerals:** lithium, cobalt, graphite, nickel, titanium, rare earths.\n- **AM / powder metallurgy:** AM powder, LPBF, EBM, HIP, metal powder and aerospace adoption.\n- **Gold / silver:** safe-haven and precious/industrial stress.\n""")\n\n    st.markdown("### Headlines")\n    if news.empty:\n        st.info("No news returned. Use fewer event terms or a simpler query.")\n    else:\n        st.dataframe(news[["title", "source", "country", "date", "url"]].head(150), use_container_width=True)\n\n    st.markdown("### Policy watch")\n    if not news.empty:\n        policy_words = ["export", "sanction", "tariff", "critical mineral", "rare earth", "defense", "procurement", "subsidy", "permit", "ban", "restriction", "powder", "titanium", "uranium"]\n        policy = news[news["title"].fillna("").str.lower().apply(lambda x: any(w in x for w in policy_words))]\n        st.dataframe(policy[["title", "source", "date", "url"]].head(80), use_container_width=True)\n        read_block("How to use policy watch", """\nPolicy watch filters headlines for export controls, sanctions, tariffs, defense procurement, mining policy, uranium, rare earths and powder/AM-related themes.\n\nThis is where material prices can disconnect from equity prices: policy can affect supply availability, not only spot prices.\n""")\n\n# -----------------------------------------------------------------------------\n# Data Quality\n# -----------------------------------------------------------------------------\nwith tabs[5]:\n    st.subheader("Data quality")\n    read_block("Why this tab matters", """\nA serious research tool must show what data it actually used.\n\nCheck this page when:\n- a ticker does not appear,\n- a model signal seems strange,\n- the period/interval combination was automatically adjusted,\n- features were built from fallback prices,\n- a news source did not load.\n""")\n    q1, q2, q3, q4 = st.columns(4)\n    q1.metric("Requested history", period)\n    q2.metric("Actual history", actual_period)\n    q3.metric("Rows", len(prices))\n    q4.metric("Feature columns", features.shape[1])\n    st.write(f"Price coverage: `{prices.index[0]}` → `{prices.index[-1]}`")\n    st.write(f"Effective shock window: `{effective_shock}`")\n    st.write(f"Feature status: `{feature_status}`")\n\n    st.markdown("### Downloaded prices")\n    st.dataframe(prices.tail(120), use_container_width=True)\n    st.markdown("### Feature table")\n    st.dataframe(features.tail(120), use_container_width=True)\n    st.markdown("### Feature metadata")\n    st.dataframe(meta, use_container_width=True)\n    st.markdown("### Material proxy resolution")\n    st.dataframe(proxy_table, use_container_width=True)\n\nst.divider()\nst.caption("Research workbench. Market data comes from free public sources and may be delayed or incomplete. Signals are diagnostics, not investment advice.")\n')
